(() => {
'use strict';
const $ = s => document.querySelector(s);
const main = $('#main');
$('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'})});
const posts = SITE.posts;
let asciiFrame = 0, asciiTimer = 0, currentRoute = '', filter = 'all', search = '', cliHistory = [], historyIndex = 0, cwd = '~';
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),2200)}
function setTheme(mode){const value=mode==='auto'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):mode;document.documentElement.dataset.theme=value;try{localStorage.setItem('siyuan-theme',value)}catch(e){}updateTheme()}
function updateTheme(){const light=document.documentElement.dataset.theme==='light';$('#theme-icon').textContent=light?'☾':'☼';$('#theme-toggle').setAttribute('aria-label',light?'切换到深色模式':'切换到浅色模式')}
$('#theme-toggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));updateTheme();
function clock(){const now=new Date();$('#local-time').textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(now);$('#year').textContent=now.getFullYear()};clock();setInterval(clock,60000);
function path(text){return `<div class="path">~ / <span>${text}</span></div>`}
function row(p){return `<a class="post-row" href="#/blog/${p.slug}"><time class="post-date" datetime="${p.date}">${p.date.slice(5).replace('-','.')}</time><span class="post-title">${esc(p.title)}</span><span class="post-tag">${p.tag}</span></a>`}
function home(){return `${path('home')}<section class="hero" aria-label="由字符构成的土星，缓缓转动"><pre id="ascii-art" class="ascii-art" aria-hidden="true"></pre><span class="art-caption">fig. 01 — a little universe</span></section><section class="intro"><h1>Hello, world<span class="accent">.</span> <span class="muted">我是 siyuan。</span></h1><p>${SITE.description}<br>这里是我的数字花园，想法缓慢生长的地方。</p><div class="intro-meta"><a href="#/about">read about me ↗</a><span class="slash">/</span><span><span class="status-dot"></span>exploring, one thing at a time</span></div></section><section aria-labelledby="latest-title"><div class="section-heading"><h2 id="latest-title">~/blog <span class="muted">— 最近写下的</span></h2><a href="#/blog">all entries [${String(posts.length).padStart(2,'0')}] ↗</a></div>${posts.slice(0,3).map(row).join('')}</section>`}
function drawAscii(){const pre=$('#ascii-art');if(!pre)return;const w=88,h=29,cx=43,cy=13.2,chars=' .·:;+=*#%@',t=asciiFrame*.018;let out='';for(let y=0;y<h;y++){for(let x=0;x<w;x++){const X=(x-cx)/1.85,Y=y-cy;const u=X*.94+Y*.34,v=-X*.34+Y*.94;const ringD=Math.sqrt((u/22)**2+(v/4.6)**2);const sphereD=(X/10)**2+(Y/10)**2;const ring=ringD>.75&&ringD<1.14;let char=' ';if(sphereD<=1){const z=Math.sqrt(1-sphereD),shade=Math.max(0,(X/10)*-.45+(Y/10)*-.55+z*.77);const bands=.09*Math.sin(Y*1.8+t)+.04*Math.sin(Y*4.7+t*1.2);char=chars[Math.max(1,Math.min(9,Math.floor((shade+bands)*8.5)))];if(ring&&v>0){const n=Math.sin(ringD*170);char=n>.4?'=':n>-.4?'·':':';}}else if(ring){const texture=Math.sin(ringD*170+t)*.5+.5;char=texture>.75?'=':texture>.4?':':'·';if((x+y)%5===0)char=' ';}else{const seed=((x*137+y*71+19)%547);if(seed===1||seed===93)char='·';if(seed===217&&x>14&&x<80)char='+';}out+=char;}out+='\n';}pre.textContent=out;asciiFrame++}
function startAscii(){drawAscii();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)asciiTimer=setInterval(()=>{if(!document.hidden)drawAscii()},160)}
function blog(){return `${path('blog/')}<div class="page-head"><h1>写下，才有迹可循<span class="accent">_</span></h1><p>一些思考，一些实践，还有暂时没有答案的问题。<span class="demo-label">演示文章</span></p></div><div class="blog-controls"><div class="filters" role="group" aria-label="文章分类">${['all','essay','code','notes'].map(t=>`<button data-filter="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div><label class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="search" placeholder="搜索文章…" aria-label="搜索文章" value="${esc(search)}"><span class="search-key" aria-hidden="true">/</span></label></div><button class="year-toggle" id="year-toggle" aria-expanded="true"><span>▾</span> 2026/</button><div id="blog-list" class="blog-list"></div><div class="list-summary"><span id="result-count"></span><span>↑ ↓ navigate &nbsp; enter open &nbsp; / search</span></div>`}
function renderList(){const list=$('#blog-list');if(!list)return;const found=posts.filter(p=>(filter==='all'||p.tag===filter)&&(`${p.title} ${p.excerpt} ${p.tag}`.toLowerCase().includes(search.toLowerCase())));list.innerHTML=found.length?found.map(row).join(''):'<p class="empty-state">没有找到匹配的文章。试试另一个关键词？</p>';$('#result-count').textContent=`${String(found.length).padStart(2,'0')} entries / ${filter==='all'?'全部文章':filter}`}
function article(slug){const p=posts.find(p=>p.slug===slug);if(!p)return notFound();const i=posts.indexOf(p),next=posts[i+1];return `${path(`blog / ${p.slug}.md`)}<a class="back-link" href="#/blog">← 返回文章目录</a><article><div class="page-head article-head"><h1>${esc(p.title)}</h1></div><div class="article-meta"><time datetime="${p.date}">${p.date}</time><span>${p.tag}</span><span>约 ${p.minutes} 分钟</span><span>演示文章</span></div><div class="prose">${p.body}</div><div class="article-bottom"><a href="#/blog"><span>cd ..</span>← 全部文章</a>${next?`<a href="#/blog/${next.slug}"><span>接着读 / next</span>${esc(next.title)} →</a>`:'<a href="#/">返回花园 →</a>'}</div></article>`}
function socialContacts(){
  const profiles=SITE.socials||{};
  const platforms=[
    {id:'instagram',name:'Instagram',mark:'◎',description:'照片与日常'},
    {id:'threads',name:'Threads',mark:'@',description:'零碎的想法'},
    {id:'wechat',name:'WeChat',mark:'◌',description:'微信联系'},
    {id:'x',name:'X',mark:'𝕏',description:'分享与交流'}
  ];
  return `<section class="social-section" aria-labelledby="social-title"><div class="social-heading"><h2 id="social-title">在别处找到我</h2><span>~/socials</span></div><div class="social-list">${platforms.map(p=>{
    const profile=profiles[p.id]||{},name=profile.username||'';
    const configured=p.id==='wechat'?Boolean(name):Boolean(profile.url);
    const caption=name?(p.id==='wechat'?name:'@'+name.replace(/^@/,'')):(profile.url?'查看主页':'待填写');
    const contents=`<span class="social-mark" aria-hidden="true">${p.mark}</span><span class="social-name">${p.name}<span>${p.description}</span></span><span class="social-account">${esc(caption)}</span><span class="social-action" aria-hidden="true">${configured?(p.id==='wechat'?'⧉':'↗'):'—'}</span>`;
    if(!configured)return `<div class="social-row social-pending" aria-label="${p.name}，待填写">${contents}</div>`;
    if(p.id==='wechat')return `<button class="social-row" id="copy-wechat" aria-label="复制微信号 ${esc(name)}">${contents}</button>`;
    return `<a class="social-row" href="${esc(profile.url)}" target="_blank" rel="noopener noreferrer" aria-label="打开 ${p.name} 主页">${contents}</a>`;
  }).join('')}</div></section>`;
}
function bindSocialContacts(){
  $('#copy-wechat')?.addEventListener('click',async()=>{
    const id=SITE.socials.wechat.username;
    try{await navigator.clipboard.writeText(id);toast('微信号已复制')}
    catch{toast('微信号：'+id+' · 可手动复制')}
  });
}
function aboutPlainText(){
  const a=SITE.about;
  return `${a.name} · ${a.lead}\n\n${a.sections.map(s=>s.title+'\n'+s.paragraphs.join('\n')).join('\n\n')}`;
}
function about(){
  const a=SITE.about;
  const values=items=>items.map(v=>`<span class="value">${esc(JSON.stringify(v))}</span>`).join(', ');
  return `${path('about.md')}<div class="page-head"><h1>你好，我是 ${esc(a.name)}<span class="accent">.</span></h1><p>${esc(a.lead)}</p></div><div class="about-terminal"><div><span class="muted">$</span> cat about.json</div><div>{</div><div>&nbsp; <span class="key">"name"</span>: <span class="value">${esc(JSON.stringify(a.name))}</span>,</div><div>&nbsp; <span class="key">"focus"</span>: [${values(a.focus)}],</div><div>&nbsp; <span class="key">"offscreen"</span>: [${values(a.offscreen)}]</div><div>}</div></div><div class="prose about-prose">${a.sections.map(s=>`<section><h2>${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}<section><h2>关于这个小站</h2><p><a href="#/blog">blog/</a> 放长一点的思考，<a href="#/travel">travel/</a> 收集旅途里的画面和随笔，<a href="#/now">now.md</a> 记录最近在做的事情。内容会慢慢补齐。</p></section></div>${socialContacts()}<p class="small-note">站内博客目前仍为示例文章。</p>`;
}
function now(){return `${path('now.md')}<div class="page-head"><h1>此刻，正在<span class="accent">_</span></h1><p>一份会随着生活变化的小清单。<span class="demo-label">演示内容</span></p></div><ul class="now-list"><li><h2>搭建自己的数字花园</h2><p>把零散的笔记慢慢整理成文章，让每一个值得留下的想法，有一个稳定的地址。</p></li><li><h2>保持输入，也留出空白</h2><p>读一些书，试一些小工具。偶尔关掉屏幕，出门走走。</p></li><li><h2>把事情做小，把时间拉长</h2><p>先完成一个可以使用的版本，再在真实使用中一点点改进。</p></li></ul><p class="small-note">这类页面叫作「now page」，用来记录一个人此刻关心的事情。<br>编辑内容文件，就可以换成你的近况。</p>`}
function notFound(){return `${path('404')}<div class="page-head"><h1>这个文件不在这里。</h1><p>也许它还没有被写下。</p></div><a href="#/" class="accent">cd ~ / 回到主页 →</a>`}
function cli(){cwd='~';return `<a class="cli-exit" href="#/">← back to gui</a><div class="cli-screen"><div class="cli-logo cli-brand" aria-label="siyuan terminal">${document.querySelector('.brand-mark').outerHTML}<span>siyuan<small>a digital garden / terminal</small></span></div><div class="cli-welcome">Welcome to siyuan's little universe.<br>输入 <span class="accent">help</span> 查看命令 · Tab 自动补全 · ↑↓ 历史记录<br><span class="muted">这是网站导航终端，命令只在当前页面内运行。</span></div><div class="cli-output" id="cli-output" role="log" aria-live="polite" aria-label="终端输出"></div><form id="cli-form" class="cli-form" autocomplete="off"><label for="cli-input"><span class="prompt-user">guest</span>@<span class="prompt-host">siyuan</span> <span class="prompt-path" id="cli-cwd">~</span></label><div class="cli-input-group"><span aria-hidden="true">❯</span><input class="cli-input" id="cli-input" aria-label="输入命令" spellcheck="false" autocapitalize="off" autocomplete="off"></div></form><div class="cli-hint">help · ls · cd blog · cat about.md · theme light · exit</div></div>`}
const help='ls                  列出当前目录\ncd <目录>           进入目录，cd .. 返回上层\ncat <文件>          读取 about.md / now.md / 文章\nopen <路径>         打开页面，如 open blog\npwd                 查看当前路径\nclear               清空终端\nhistory             查看命令历史\ntheme light|dark     切换主题\nexit                返回图形主页\n\nTab 补全 · ↑↓ 历史 · Ctrl+L 清屏';
function cliReply(command,body){const out=$('#cli-output');const entry=document.createElement('div');entry.className='cli-entry';entry.innerHTML=`<div class="cli-command"><span class="prompt-user">guest</span>@<span class="prompt-host">siyuan</span> <span class="prompt-path">${esc(cwd)}</span> ❯ ${esc(command)}</div><div>${body}</div>`;out.append(entry);$('#cli-cwd').textContent=cwd;$('#cli-input').scrollIntoView({block:'nearest'})}
function runCommand(raw){const command=raw.trim();if(!command)return;cliHistory.push(command);historyIndex=cliHistory.length;const [cmd,...args]=command.split(/\s+/),arg=args.join(' ').replace(/^~\/?/,'').replace(/^\//,'');let response='';switch(cmd.toLowerCase()){
case 'help':response=esc(help);break;
case 'ls':response=cwd==='~/blog'?posts.map(p=>`<a href="#/blog/${p.slug}">${p.date}  ${esc(p.slug)}.md</a>`).join('\n'):'<span class="accent">blog/    travel/</span>\nabout.md  now.md';break;
case 'pwd':response=esc('/home/siyuan'+(cwd==='~'?'':cwd.slice(1)));break;
case 'cd':if(!arg||arg==='..'||arg==='/'){cwd='~';response='~'}else if(arg==='blog'||arg==='blog/'){cwd='~/blog';response='进入 blog/，输入 ls 查看文章。'}else if(arg==='travel'||arg==='travel/'){location.hash='/travel';return}else response=esc(`cd: 找不到目录「${arg}」。试试 cd blog。`);break;
case 'cat':if(arg==='about.md'){response=esc(aboutPlainText())}else if(arg==='now.md'){response='→ 搭建自己的数字花园\n→ 保持输入，也留出空白\n→ 把事情做小，把时间拉长'}else{const name=arg.replace(/^blog\//,'').replace(/\.md$/,'');const p=posts.find(p=>p.slug===name);response=p?`<strong>${esc(p.title)}</strong>\n<span class="muted">${p.date} · ${p.tag} · 演示文章</span><div class="prose">${p.body}</div>`:esc('cat: 找不到这个文件。输入 ls 查看可用内容。')}break;
case 'open':{const dest=arg.replace(/\/$/,'').replace(/\.md$/,'');if(['','home','about','blog','travel','now','cli'].includes(dest)){location.hash='/'+(dest==='home'?'':dest);return}const p=posts.find(p=>p.slug===dest.replace(/^blog\//,''));if(p){location.hash='/blog/'+p.slug;return}response=esc(`open: 找不到「${arg}」。`);break}
case 'theme':if(['dark','light','auto'].includes(arg)){setTheme(arg);response=esc('theme → '+arg)}else response='用法：theme light / dark / auto';break;
case 'clear':$('#cli-output').innerHTML='';return;
case 'history':response=cliHistory.map((c,i)=>`${String(i+1).padStart(2,' ')}  ${esc(c)}`).join('\n');break;
case 'exit':location.hash='/';return;
default:response=esc(`${cmd}: 没有这个命令。输入 help 查看可用命令。`)
}cliReply(command,response)}
function setupCli(){const input=$('#cli-input');$('#cli-form').addEventListener('submit',e=>{e.preventDefault();const raw=input.value;input.value='';runCommand(raw)});input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=cliHistory[historyIndex]||''}else if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(cliHistory.length,historyIndex+1);input.value=cliHistory[historyIndex]||''}else if(e.key==='Tab'){e.preventDefault();const val=input.value,commands=['help','ls','cd','cat','open','pwd','clear','history','theme','exit'];let options;if(!val.includes(' ')){options=commands.filter(c=>c.startsWith(val))}else{const prefix=val.slice(val.lastIndexOf(' ')+1),head=val.slice(0,val.lastIndexOf(' ')+1);options=['blog/','travel/','about.md','now.md',...posts.map(p=>p.slug+'.md'),'dark','light'].filter(c=>c.startsWith(prefix)).map(c=>head+c)}if(options.length===1)input.value=options[0];else if(options.length>1)toast(options.slice(0,5).join(' · '))}else if(e.ctrlKey&&e.key==='l'){e.preventDefault();$('#cli-output').innerHTML=''}});input.focus({preventScroll:true})}
function render(){Travel.unmount();clearInterval(asciiTimer);const route=decodeURIComponent(location.hash.slice(1)||'/');currentRoute=route;const parts=route.split('/').filter(Boolean),section=parts[0]||'home';document.querySelectorAll('.directory a').forEach(a=>{const active=a.dataset.route===section;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.innerHTML=section==='home'?home():section==='blog'?(parts[1]?article(parts[1]):blog()):section==='travel'?Travel.page():section==='about'?about():section==='now'?now():section==='cli'?cli():notFound();const title=section==='blog'&&parts[1]?posts.find(p=>p.slug===parts[1])?.title:({home:'数字花园',blog:'文字与思考',about:'关于',travel:'旅行与随笔',now:'此刻',cli:'Terminal'}[section]||'404');document.title=`${title} · siyuan`;window.scrollTo(0,0);if(section==='home')startAscii();if(section==='blog'&&!parts[1]){renderList();$('#search').addEventListener('input',e=>{search=e.target.value;renderList()});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderList()}));$('#year-toggle').addEventListener('click',()=>{const b=$('#year-toggle'),open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));b.querySelector('span').textContent=open?'▸':'▾';$('#blog-list').hidden=open})}if(section==='about')bindSocialContacts();if(section==='cli')setupCli();if(section==='travel')Travel.mount();progress()}
function progress(){const el=$('#reading-progress');if(currentRoute.startsWith('/blog/')){const length=document.documentElement.scrollHeight-innerHeight;el.style.width=length>0?`${Math.min(100,scrollY/length*100)}%`:'0'}else el.style.width='0'}
window.addEventListener('scroll',progress,{passive:true});window.addEventListener('hashchange',()=>{render();if(!currentRoute.startsWith('/cli'))main.focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(currentRoute!=='/blog')return;if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}if(['ArrowDown','ArrowUp'].includes(e.key)&&document.activeElement.tagName!=='INPUT'){const rows=[...document.querySelectorAll('#blog-list .post-row')];if(!rows.length||$('#blog-list').hidden)return;e.preventDefault();const current=rows.indexOf(document.activeElement);const idx=e.key==='ArrowDown'?Math.min(rows.length-1,current+1):Math.max(0,current<0?rows.length-1:current-1);rows[idx].focus()}});render();
})();
